  console.log('bad slug ->',l.status,JSON.stringify((await l.json()).message));
  const ok=await post({...cust,lines:[{kind:'product',slug:'reading-nook',qty:2},{kind:'pack',slugs:['tbr-mountain','tea-and-chapter','sleepy-cat-books'],qty:1}],cardNumber:'4242424242424242',cardExpiry:'11 / 29',cardCvc:'123'});
