node -e "
const app=require('./server').app;
const base='http://127.0.0.1:4325';
const server=app.listen(4325,async()=>{
  const pages=['/','/shop','/bundles','/cart','/checkout','/about','/faq','/shipping','/contact','/product/reading-nook','/product/night-reader'];
  let bad=0;
  for(const p of pages){
    const html=await (await fetch(base+p)).text();
    // strip script/style then tags, leaving visible text
    const text=html.replace(/<script[\s\S]*?<\/script>/g,'').replace(/<style[\s\S]*?<\/style>/g,'')
      .replace(/<svg[\s\S]*?<\/svg>/g,'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ');
    const hits=[];
    if(text.includes('\u2014')) hits.push('em-dash');
    if(text.includes('\u2013')) hits.push('en-dash');
    if(/[;]/.test(text)) hits.push('semicolon');
    if(/\bbest[- ]?sell|\bselling\b|\blimited\b|\bhandmade by|\bcustomers love|\b5-star\b|\bperfect gift\b/i.test(text)) hits.push('stock-phrase');
    if(/\b\d+ (happy )?customers\b|\b\d+\+ reviews\b|\bsold \d+\b/i.test(text)) hits.push('invented-proof');
    if(hits.length){bad++;console.log(p, hits.join(','));}
  }
  console.log(bad===0?'clean: no em dashes, en dashes, semicolons, stock phrases or invented proof on any page':'issues above');
  server.close();process.exit(0);
});
"

